from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Alarm(EmssimCommand):
    def __init__(self, method="alarm", timeout=60, rpc_connection_name='localRPC'):
        super(Alarm, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Alarm, self).on_new_data(**data)
        if "msg" in data:
            if (data["msg"] == "Alarm history is empty"):
                self._ret['alarm_table'] = 'EMPTY'

            elif (data["msg"] == "Alarm table"):
                self._ret['alarm_table'] = data['table']
        elif ("status" in data):
            self._ret["status"] = data["status"]
